 */
function frameConnTurnUiCommittedActionCanRoll(
  action
) {
  if (
    !action?.id
  ) {
    return false;
  }


  return (
    !FRAME_CONN_TURN_UI_NO_ROLL_ACTION_IDS
      .has(
        action.id
      ) &&
    !FRAME_CONN_TURN_UI_EXECUTE_ONLY_ACTION_IDS
      .has(
        action.id
      )
  );
}


/**
 * Determine whether a committed action has a current execution
 * workflow, regardless of whether that workflow rolls dice.
 */
function frameConnTurnUiCommittedActionCanExecute(
  action
) {
  if (
    !action?.id
  ) {
    return false;
  }


  return (
    !FRAME_CONN_TURN_UI_NO_ROLL_ACTION_IDS
      .has(
        action.id
      )
  );
}


/**
 * Build the presentation-only execution control contract consumed
 * by the Application UI.
 *
 * The control carries both the committed-entry id and action id so
 * execution can address the exact committed action rather than only
 * the underlying universal-action definition.
 */
function buildFrameConnTurnCommittedActionExecutionPresentation(
  action,
  entry
) {
  const committedActionId =
    entry?.id ??
    null;

  const actionId =
    entry?.actionId ??
    action?.id ??
    null;

  const executed =
    Boolean(
      entry?.executed
    );

  const executable =
    Boolean(
      committedActionId &&
      actionId
    );

  const canRoll =
    frameConnTurnUiCommittedActionCanRoll(
      action
    );

  const canExecute =
    frameConnTurnUiCommittedActionCanExecute(
      action
    );

  const showExecuteControl =
    Boolean(
      executable &&
      canExecute &&
      !executed
    );


  return Object.freeze({
    committedActionId,

    actionId,

    executable,

    canRoll,

    canExecute,

    showExecuteControl,

    requiresTarget:
      Boolean(
        action?.requiresTarget
      ),

    targetType:
      action?.targetType ??
      null,

    control:
      Object.freeze({
        visible:
          showExecuteControl,

        kind:
          canRoll
            ? "roll"
            : "execute",

        icon:
          canRoll
